  "settings.modelProvider.fieldHelp": "Tietoja: {field}",
  "settings.modelProvider.help.contextWindow": "Kontekstikapasiteetti, jonka malli pystyy käsittelemään kerrallaan, tokeneina. ZAICODE käyttää tätä kontekstin hallintaan.\nÄlä ylitä mallin todellista rajaa.",
  "settings.modelProvider.help.maxOutputTokens": "Yksittäisen mallipyynnön suurin generoitavien tokenien määrä.\nÄlä ylitä mallin todellista rajaa.",
  "settings.modelProvider.help.inputModalities": "Aseta sisältötyypit, joita malli voi vastaanottaa:\n\n- **Teksti**: Vastaanottaa tekstisisältöä. Pakollinen.\n- **Kuvat**: Vastaanottaa kuvasisältöä.\n- **Video**: Vastaanottaa videosisältöä.\n- **PDF**: Vastaanottaa PDF-asiakirjoja suoraan.",
  "settings.modelProvider.help.outputModalities": "Mallin vastausten sisältötyyppi. Tällä hetkellä vain teksti tuetaan.",
  "settings.modelProvider.help.capabilities": "- **Rakennettu tuloste**: Tukee JSON Schema -rajoitteita tuloskentille, tyypeille ja rakenteelle.\n- **Natiivi verkkohaku**: Tukee malli-API:n sisäänrakennettua verkkohakutoimintoa.\n- **Järjestelmäviestit keskustelun aikana**: Tukee järjestelmäohjeiden lisäämistä keskustelun aikana.\n\nÄlä ota käyttöön ominaisuuksia, joita malli ei tue.",
  "settings.modelProvider.help.reasoningLevelsOrdered": "Aseta päässä käytettävissä olevat päättelytasot. **Ne on järjestettävä pienimmästä suurimpaen päättelyrasitukseen**.\nÄlä määritä päättelytasoja, joita malli ei tue.",
  "settings.modelProvider.help.reasoningLevelMapping": "Kartoita nykyinen päättelytaso `reasoningLevel` malli-API:n pyyntökentiksi CEL-lausekkeella. Lausekkeen palauttama JSON-objekti yhdistetään lähtevään pyyntörungon.",
  "settings.modelProvider.help.advanced": "**MFJS-työkaluskeema**: Ottaa käyttöön Moonshot Flavored JSON Schema -yhteensopivuuden, jota käytetään yleisesti Moonshotin Kimi-malli-API:ssa. Ota käyttöön vain, kun malli-API vaatii tämän muodon.",
  "settings.modelProvider.help.followRecommendedConfig": "Vastaa suositeltua määritystä mallitunnusteen, Base URL -osoitteen ja API-muodon perusteella. ZAICODE päivittää suosituksia jatkuvasti ja synkronoi ne automaattisesti.\nKun muutat asetusta manuaalisesti, siitä tulee hallinnassa oma asetus, joka ei enää seuraa suosituksia; muut asetukset pysyvät älykkään määrityksen hallinnassa.",
